"""Test block SidePanel (Navigation): The app's main navigation on the left: sections, collapsible groups and count badges, hidden on the phone until opened.

Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/navigation/SidePanel.md and its markup
(kit/blocks/navigation/SidePanel.html; source af63b97ce10b), with the vocabulary in
functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.

Steps (e2e):
  When I go to {section} in the side panel
  Then the side panel shows {section} as the current page
  Then the side panel badge for {section} says {count}
  When I open or close the group {name}
  When I add a collection
  When I toggle the side panel
  Then the side panel is open
  Then the side panel is closed
  Then the side panel is in the {state} state
States (from the card): Open, Collapsed, Phone, closed, Phone, open, Group collapsed, Count changes, Long names, No
permission. Checked by the state step: Open, Collapsed.
"""
from __future__ import annotations

import re

from functional import Registry
from functional import primitives as p

BLOCK = "SidePanel"
ROUTE = ""
STATES = ["Open", "Collapsed", "Phone, closed", "Phone, open", "Group collapsed", "Count changes", "Long names", "No permission"]
DEFAULT_STATE = "Open"
CHECKED_STATES = ["Open", "Collapsed"]
DEMO = ["kit/blocks/navigation/SidePanel.html"]
SELF_TEST = [
    "Then the side panel is open",
    "Then the side panel shows Home as the current page",
    "Then the side panel badge for Notes says 12",
    "Then the side panel badge for Inbox says 3",
    "When I open or close the group \"Japanese 1\"",
    "When I go to Notes in the side panel",
    "Then the side panel is in the \"Open\" state",
]

steps = Registry(block=BLOCK)


class SidePanel:
    """The SidePanel block on a page: its controls, found as a person finds them (role and name, label, text)."""

    def __init__(self, page, base_url: str = ""):
        self.page = page
        self.base_url = base_url

    def panel(self):
        return p.control(self.page, css="#sidebar", block=BLOCK)

    def nav(self):
        return p.control(self.panel(), role="navigation", name="Main", block=BLOCK)

    def link(self, section):
        return p.control(self.nav(), role="link", name=re.compile('^' + re.escape(str(section))), block=BLOCK)

    def group(self, name):
        return p.control(self.nav(), text=str(name), block=BLOCK)

    def new_collection(self):
        return p.control(self.nav(), role="button", name="New Collection", block=BLOCK)

    def toggle(self):
        return p.control(self.page, role="button", name="Show or hide the side panel", block=BLOCK)

    def expect_state(self, state: str) -> None:
        """Check one of the card's states: Open, Collapsed."""
        b = self
        if state == "Open":
            p.expect_attribute(b.panel(), "aria-hidden", "false")
        elif state == "Collapsed":
            p.expect_attribute(b.panel(), "aria-hidden", "true")
        else:
            raise AssertionError(f"SidePanel has no check for the state {state!r}; checked: " + ", ".join(CHECKED_STATES))


@steps.step("When I go to {section} in the side panel", level="e2e")
def when_i_go_to_section_in_the_side_panel(world, section):
    b = SidePanel(world.page, getattr(world, "base_url", ""))
    p.click(b.link(section))


@steps.step("Then the side panel shows {section} as the current page", level="e2e")
def then_the_side_panel_shows_section_as_the_current_page(world, section):
    b = SidePanel(world.page, getattr(world, "base_url", ""))
    p.expect_attribute(b.link(section), "aria-current", "page")


@steps.step("Then the side panel badge for {section} says {count}", level="e2e")
def then_the_side_panel_badge_for_section_says_count(world, section, count):
    b = SidePanel(world.page, getattr(world, "base_url", ""))
    p.expect_text(b.link(section), str(count))


@steps.step("When I open or close the group {name}", level="e2e")
def when_i_open_or_close_the_group_name(world, name):
    b = SidePanel(world.page, getattr(world, "base_url", ""))
    p.click(b.group(name))


@steps.step("When I add a collection", level="e2e")
def when_i_add_a_collection(world):
    b = SidePanel(world.page, getattr(world, "base_url", ""))
    p.click(b.new_collection())


@steps.step("When I toggle the side panel", level="e2e")
def when_i_toggle_the_side_panel(world):
    b = SidePanel(world.page, getattr(world, "base_url", ""))
    p.click(b.toggle())


@steps.step("Then the side panel is open", level="e2e")
def then_the_side_panel_is_open(world):
    b = SidePanel(world.page, getattr(world, "base_url", ""))
    p.expect_attribute(b.panel(), "aria-hidden", "false")


@steps.step("Then the side panel is closed", level="e2e")
def then_the_side_panel_is_closed(world):
    b = SidePanel(world.page, getattr(world, "base_url", ""))
    p.expect_attribute(b.panel(), "aria-hidden", "true")


@steps.step("Then the side panel is in the {state} state", level="e2e")
def then_the_side_panel_is_in_the_state_state(world, state):
    b = SidePanel(world.page, getattr(world, "base_url", ""))
    b.expect_state(state)
